const ctx = canvas.getContext("2d");
const COLS = 32;
const ROWS = 24;
const CELL = 20;
const STEP_MS = 105;

let snake;
let dir;
let pendingDir;
let food;
let score;
let foods;
let running;
let timer;
let lastTick = 0;
let raf = 0;

let highScore = Number(sessionStorage.getItem("grafana-snake-high-score") || 0);

function pad(n) {
  return String(n).padStart(6, "0");
}

function randomFood() {
  let candidate;
  do {
    candidate = {
      x: Math.floor(Math.random() * COLS),
      y: Math.floor(Math.random() * ROWS)
    };
  } while (snake.some((p) => p.x === candidate.x && p.y === candidate.y));
  return candidate;
}

function updateMetrics() {
  scoreEl.textContent = pad(score);
  highEl.textContent = pad(highScore);
  lengthEl.textContent = String(snake.length);
  foodEl.textContent = String(foods);

  if (running) {
    statusText.textContent = "RUNNING";
    dot.style.background = "#73bf69";
    dot.style.boxShadow = "0 0 8px rgba(115,191,105,.45)";
  } else {
    statusText.textContent = "GAME OVER";
    dot.style.background = "#f2495c";
    dot.style.boxShadow = "0 0 8px rgba(242,73,92,.45)";
  }
}

function reset() {
  snake = [
    { x: 10, y: 12 },
    { x: 9, y: 12 },
    { x: 8, y: 12 }
  ];
  dir = { x: 1, y: 0 };
  pendingDir = { x: 1, y: 0 };
  score = 0;
  foods = 0;
  running = true;
  lastTick = performance.now();
  food = randomFood();
  updateMetrics();
  draw();
  host.focus({ preventScroll: true });
}

function gameOver() {
  running = false;
  arcadeTone(110,.24,'sawtooth');
  if (score > highScore) {
    highScore = score;
    sessionStorage.setItem("grafana-snake-high-score", String(highScore));
  }
  updateMetrics();
  draw();
}

function tick() {
  if (!running) return;

  dir = pendingDir;
  const head = {
    x: snake[0].x + dir.x,
    y: snake[0].y + dir.y
  };

  if (
    head.x < 0 ||
    head.x >= COLS ||
    head.y < 0 ||
    head.y >= ROWS ||
    snake.some((p) => p.x === head.x && p.y === head.y)
  ) {
    gameOver();
    return;
  }

  snake.unshift(head);

  if (head.x === food.x && head.y === food.y) {
    foods += 1;
    score += 10;
    arcadeTone(740,.08,'sine');
    if (score > highScore) {
      highScore = score;
      sessionStorage.setItem("grafana-snake-high-score", String(highScore));
    }
    food = randomFood();
  } else {
    snake.pop();
  }

  updateMetrics();
}

function drawGrid() {
  ctx.strokeStyle = "rgba(255,255,255,0.035)";
  ctx.lineWidth = 1;
  for (let x = 0; x <= canvas.width; x += CELL) {
    ctx.beginPath();
    ctx.moveTo(x + 0.5, 0);
    ctx.lineTo(x + 0.5, canvas.height);
    ctx.stroke();
  }
  for (let y = 0; y <= canvas.height; y += CELL) {
    ctx.beginPath();
    ctx.moveTo(0, y + 0.5);
    ctx.lineTo(canvas.width, y + 0.5);
    ctx.stroke();
  }
}

function draw() {
  ctx.fillStyle = "#0b0c0e";
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  drawGrid();

  // Food: Grafana-orange "data point".
  ctx.fillStyle = "#ff9830";
  ctx.beginPath();
  ctx.arc(
    food.x * CELL + CELL / 2,
    food.y * CELL + CELL / 2,
    CELL * 0.34,
    0,
    Math.PI * 2
  );
  ctx.fill();

  snake.forEach((p, i) => {
    ctx.fillStyle = i === 0 ? "#73bf69" : "#5794f2";
    const inset = i === 0 ? 2 : 3;
    ctx.fillRect(
      p.x * CELL + inset,
      p.y * CELL + inset,
      CELL - inset * 2,
      CELL - inset * 2
    );
  });

  if (!running) {
    ctx.fillStyle = "rgba(11,12,14,.78)";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.textAlign = "center";
    ctx.fillStyle = "#f2495c";
    ctx.font = "600 34px Inter, Arial, sans-serif";
    ctx.fillText("ALERTING: SNAKE DOWN", canvas.width / 2, canvas.height / 2 - 18);

    ctx.fillStyle = "#d8d9da";
    ctx.font = "16px Roboto Mono, monospace";
    ctx.fillText("Press SPACE to restart", canvas.width / 2, canvas.height / 2 + 24);
  }
}

function frame(now) {
  if (!host.isConnected) {
    cancelAnimationFrame(raf);
    try { if (arcadeAudio) arcadeAudio.close(); } catch (_) {}
    return;
  }
  if (running && now - lastTick >= STEP_MS) {
    tick();
    lastTick = now;
  }
  draw();
  raf = requestAnimationFrame(frame);
}

function setDirection(x, y) {
  // Block 180-degree reversals.
  if (x === -dir.x && y === -dir.y) return;
  pendingDir = { x, y };
}

function onKeyDown(event) {
  const key = event.key.toLowerCase();
  const gameKeys = ["arrowup", "arrowdown", "arrowleft", "arrowright", "w", "a", "s", "d", " "];

  if (!gameKeys.includes(key)) return;

  event.preventDefault();
  event.stopPropagation();

  if (key === "arrowup" || key === "w") setDirection(0, -1);
  if (key === "arrowdown" || key === "s") setDirection(0, 1);
  if (key === "arrowleft" || key === "a") setDirection(-1, 0);
  if (key === "arrowright" || key === "d") setDirection(1, 0);
  if (key === " ") reset();
}

function onPointerDown() {
  host.focus({ preventScroll: true });
}

host.addEventListener("keydown", onKeyDown);
host.addEventListener("pointerdown", onPointerDown);

this.grafanaSnakeCleanup = () => {
  host.removeEventListener("keydown", onKeyDown);
  host.removeEventListener("pointerdown", onPointerDown);
  if (raf) cancelAnimationFrame(raf);
  if (timer) clearInterval(timer);
};

reset();
raf = requestAnimationFrame(frame);
